steps.expression:
// A long step does not have to stay silent until it ends. Raising the
// boundary event lets a second branch report progress while this one
// keeps working — the event is non-interrupting.
for (int part = 1; part <= 3; part++)
{
    Logger.LogInformation($"part {part} done");

    // The name in brackets is the id of the boundary event on the
    // diagram. Get it wrong and the engine raises BoundaryEventNotFound.
    Action.BoundaryEvents["Event_Progress"].Raise($"part {part} of 3");
}
return new JobRequest() { jobId = Input.jobId };
